// GIVEN by the paper — do not change.
public interface IStringNumberTool {
    String buildAcronym(String string);

    String decimalToBinary(int n);
}

import java.util.Scanner;

// GIVEN by the paper (like the PE harness) — do not change.
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        IStringNumberTool t = new MyStringNumberTool();
        while (sc.hasNextLine()) {
            System.out.println("1. Test buildAcronym()");
            System.out.println("2. Test decimalToBinary()");
            System.out.print("Enter TC (1 or 2): ");
            int tc = Integer.parseInt(sc.nextLine().trim());
            System.out.print("Enter a value: ");
            String s = sc.nextLine();
            System.out.println();
            System.out.println("OUTPUT:");
            System.out.println(tc == 1 ? String.valueOf(t.buildAcronym(s)) : String.valueOf(t.decimalToBinary(Integer.parseInt(s.trim()))));
        }
    }
}

public class MyStringNumberTool implements IStringNumberTool {
    @Override
    public String buildAcronym(String string) {
        StringBuilder sb = new StringBuilder();
        for (String w : string.split(" ")) {
            if (w.isEmpty()) {
                continue;
            }
            char first = w.charAt(0);
            if ((first >= 'a' && first <= 'z') || (first >= 'A' && first <= 'Z')) {
                sb.append(Character.toUpperCase(first));
            }
        }
        return sb.toString();
    }

    @Override
    public String decimalToBinary(int n) {
        if (n == 0) {
            return "0";
        }
        StringBuilder sb = new StringBuilder();
        while (n > 0) {
            sb.append(n % 2);
            n /= 2;
        }
        return sb.reverse().toString();
    }
}

